INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1208, 51, 'CC1', 'CC1', 'Création de supports de communication', 'Création de supports de communication', 'CICADA', 'Validé', 'CC1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1209, 51, 'CC1.1', 'CC1_1', 'Création de supports pédagogiques', 'Création de supports pédagogiques', 'CICADA', 'Validé', 'CC1.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1210, 51, 'CC1.1.1', 'CC1_1_1', 'Création de panneaux d''accueil et d''information', 'Création de panneaux d''accueil et d''information', 'CICADA', 'Validé', 'CC1.1.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1211, 51, 'CC1.1.2', 'CC1_1_2', 'Création de panneaux d''interprétation', 'Création de panneaux d''interprétation', 'CICADA', 'Validé', 'CC1.1.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1212, 51, 'CC1.2', 'CC1_2', 'Création de supports d''information', 'Création de supports d''information', 'CICADA', 'Validé', 'CC1.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1213, 51, 'CC1.2.1', 'CC1_2_1', 'Création de panneaux signalétiques', 'Création de panneaux signalétiques', 'CICADA', 'Validé', 'CC1.2.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1214, 51, 'CC1.2.2', 'CC1_2_2', 'Création de panneaux pour réglementation', 'Création de panneaux pour réglementation', 'CICADA', 'Validé', 'CC1.2.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1215, 51, 'CC1.2.3', 'CC1_2_3', 'Création de panneaux d''information sur les risques', 'Création de panneaux d''information sur les risques', 'CICADA', 'Validé', 'CC1.2.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1216, 51, 'CC1.3', 'CC1_3', 'Création de supports de communication', 'Création de supports de communication', 'CICADA', 'Validé', 'CC1.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1217, 51, 'CC2', 'CC2', 'Autres actions de communication', 'Autres actions de communication', 'CICADA', 'Validé', 'CC2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1300, 64, '1', '1', 'Physiques', 'Pressions physiques et mécaniques exercées directement par l''homme ou à  l''aide d''une machine sur le milieu\n\nExemples : Pressions physiques : Dégradation, Dérangement, Prélèvement', 'CARET', 'Validé', '1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1301, 64, '1.1', '1_1', 'Perte physique permanente de l''habitat naturel ou semi-naturel', 'Perte physique permanente d''un habitat naturel ou semi-naturel au profit d''un espace artificialisé (imperméabilisation) ou d''un autre milieu (eg. habitat marin vers habitat terrestre)\n\nExemples : Artificialisation/Imperméabilisation des sols', 'CARET', 'Validé', '1.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1302, 64, '1.2', '1_2', 'Modification permanente de type d''habitat naturel ou semi-naturel', 'Modification permanente d''un habitat naturel ou semi-naturel vers un autre type d''habitat naturel ou semi-naturel (du même milieu)\n\nExemples : Transgression marine, Déboisement, Plantation (enrésinement), Altération physique, Dégradation de roches et d''habitats naturels fixés', 'CARET', 'Validé', '1.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1303, 64, '1.3', '1_3', 'Perturbation physique temporaire du substrat (eg. sol, fond marin)', 'Perturbation physique temporaire et réversible du substrat (eg. modification du fond marin à  partir duquel il peut se rétablir si l''activité à  l''origine de la pression perturbatrice cesse)\n\nExemples : Dégradation temporaire', 'CARET', 'Validé', '1.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1304, 64, '1.3.1', '1_3_1', 'Abrasion du substrat', 'Frottement de la surface ou pénétration plus ou moins profonde du substrat par des objets mécaniques\n\nExemples : Abrasion, Erosion', 'CARET', 'Validé', '1.3.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1305, 64, '1.3.2', '1_3_2', 'Extraction du substrat', 'Suppression de substrat, y compris des éléments biogéniques, qui expose du substrat de même nature que le substrat d''origine ou bien qui expose temporairement du substrat de nature différente mais qui permettra la recolonisation par les communautés d''origine. (eg. extraction de minéraux marins où une proportion de sables ou de graviers du fond marin est éliminée mais une couche résiduelle du fond marin est similaire à  la structure d''avant le dragage et, en tant que telle, les communautés biologiques pourraient recoloniser)\n\nExemples : Extraction de tourbe, Exploitation minière, Extraction de sables coquillier, Dragage', 'CARET', 'Validé', '1.3.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1306, 64, '1.3.3', '1_3_3', 'Compression verticale du substrat', 'Compression verticale du substrat par des objets mécaniques ou par l''Homme (écrasement)\n\nExemples : Tassement /Compactage du sol', 'CARET', 'Validé', '1.3.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1307, 64, '1.3.4', '1_3_4', 'Remaniement du substrat', 'Déplacement et réarrangement du substrat sans perte de matière.\n\nExemples : Remise en suspension de sédiment, Remaniement de sable de plage', 'CARET', 'Validé', '1.3.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1308, 64, '1.3.5', '1_3_5', 'Dépôt de matériel sur le substrat', 'Addition de matériel sur le substrat. Le matériel peut être de même nature ou de nature différente que le substrat.\n\nExemples : Rechargement de plages', 'CARET', 'Validé', '1.3.5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1309, 64, '1.4', '1_4', 'Interaction avec les espèces sauvages', 'Interaction directe des espèces avec l''Homme ou des structures anthropiques et véhicules\n\nExemples : Interaction avec les espèces sauvages : Obstacles, Dérangements, Collisions, Prélèvements', 'CARET', 'Validé', '1.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1310, 64, '1.4.1', '1_4_1', 'Obstacle au mouvement des espèces sauvages', 'Obstruction physique partielle ou temporaire aux déplacements des espèces, qu''ils soient locaux ou à  large échelle (migration).\n\nExemples : Présence d''obtacles artificiels (routes, voies ferrées, éoliennes, canaux, barrages, écluses, seuils, etc.) ; Obstruction de cavités', 'CARET', 'Validé', '1.4.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1311, 64, '1.4.2', '1_4_2', 'Dérangement des espèces sauvages', 'Dérangement visuel, olfactif ou sonore (cf pression 2.4) des espèces\n\nExemples : Dérangements sonores (cris, conversations bruyantes, aboiement de chiens, engins motorisés) ; Dérangements visuels (présence humaine trop proche, pollution lumineuse) ; Dérangements physiques direct (poursuite d''animaux, piétinement) ; Dérangements olfactifs (Odeur humaine ou de chiens)', 'CARET', 'Validé', '1.4.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1312, 64, '1.4.3', '1_4_3', 'Interaction physique non intentionnelle avec des espèces sauvages', 'Interaction par collision des espèces avec des structures statiques ou mobiles ou étouffement\n\nExemples : Collision sur route (écrasement) ; Electrocution de la faune sur les lignes hautes tension', 'CARET', 'Validé', '1.4.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1313, 64, '1.4.4', '1_4_4', 'Prélèvement d''espèces sauvages', 'Consommation de ressources biologiques sauvages, y compris les effets de récolte délibérés et non intentionnels, la persécution ou le contrôle d''espèces spécifiques\n\nExemples : Cueillette, Récolte , Collecte, Braconnage, Chasse, Piégeage, Prélèvements intentionnels ou accidentels,', 'CARET', 'Validé', '1.4.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1314, 64, '1.4.4.1', '1_4_4_1', 'Prélèvement intentionnel d''espèces sauvages', 'Prêlèvement d''espèces ciblées par une activité de récolte récréative ou commerciale, amateur ou professionnelle. Cette pression concerne seulement l''aspect « biologique » du prélèvement direct et voulu de biote, et pas l''aspect mécanique (type abrasion).\n\nExemples : Cueillette de plantes, Récolte de champignons, Récolte de bois, Collecte d’algues marines, Braconnage des œufs de tortues marines, Prélèvements de poissons, Chasse, Chasse sous-marine, Captures et prélèvements à des fins scientifiques', 'CARET', 'Validé', '1.4.4.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1315, 64, '1.4.4.2', '1_4_4_2', 'Prélèvement accidentel d''espèces sauvages', 'Prélèvement d''espèces non ciblées par une activité de récolte récréative ou commerciale, amateur ou professionnelle (ciblant une autre espèce). Cette pression concerne seulement l''aspect « biologique » du prélèvement direct et voulu de biote, et pas l''aspect mécanique (type abrasion).\n\nExemples : Capture par filet de pêche', 'CARET', 'Validé', '1.4.4.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1316, 64, '2', '2', 'Pollutions et modifications physico-chimiques', 'Pressions indirectes de l''homme sur le milieu par introduction d''objets manufacturés, de substances ou par modifications de paramètres physico-chimiques\n\nExemples : Pollution et modification des conditions physico-chimiques', 'CARET', 'Validé', '2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1317, 64, '2.1', '2_1', 'Modifications hydrologiques', 'Modifications des conditions hydrologiques de la masse d''eau\n\nExemples : Modification des conditions hydrologiques', 'CARET', 'Validé', '2.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1318, 64, '2.1.1', '2_1_1', 'Modification des conditions hydrodynamiques', 'Changement intervenant dans le régime des marées, des vagues ou dans l''action du courant d''un cours d''eau\n\nExemples : Pompage sur les eaux souterraines, Prélèvements sur les eaux de surface, Dérivation des eaux de surface, Détournement d''un cours d''eau, Obstacles à l''écoulement de l''eau, Modification de la morphologie des cours d''eau', 'CARET', 'Validé', '2.1.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1319, 64, '2.1.2', '2_1_2', 'Modification de la charge en particules', 'Augmentation de la charge en sédiment ou matière organique (particulaire ou dissoute) de l''eau. Peut se rapporter à  la turbidité de l''eau.\n\nExemples : Remise en suspension de sédiments ; Apports de matières organiques dissoutes et particulaires', 'CARET', 'Validé', '2.1.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1320, 64, '2.2', '2_2', 'Modifications des paramètres physico-chimiques du milieu', 'Modifications des paramètres physico-chimiques du milieu\n\nExemples : Modification des paramètres physico-chimiques', 'CARET', 'Validé', '2.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1321, 64, '2.2.1', '2_2_1', 'Modification de la salinité du milieu', 'Augmentation ou réduction de la salinité locale de l''eau hors de la fourchette normale de salinité du biotope / de l''habitat considéré\n\nExemples : Augmentation de la salinité ; Réduction de la salinité', 'CARET', 'Validé', '2.2.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1322, 64, '2.2.2', '2_2_2', 'Modification de la température du milieu', 'Augmentation ou réduction locale de la température de l''eau ou du sédiment\n\nExemples : Augmentation de la température ; Réduction de la température', 'CARET', 'Validé', '2.2.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1323, 64, '2.2.3', '2_2_3', 'Modification du régime éolien du milieu', 'Modification locale du régime éolien\n\nExemples : Augmentation de la vitesse moyenne du vent ; Rafales de vent, tempête, tornade', 'CARET', 'Validé', '2.2.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1324, 64, '2.2.4', '2_2_4', 'Modification du pH du milieu', 'Augmentation ou réduction locale du pH du milieu\n\nExemples : Acidification des océans ;  Acidification des sols', 'CARET', 'Validé', '2.2.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1325, 64, '2.2.5', '2_2_5', 'Modifications des apports en nutriments dans le milieu', 'Augmentation ou réduction locale des concentrations en un ou plusieurs nutriments (azote, phosphore, silicium, fer, etc.) par rapport aux concentrations de référence du milieu\n\nExemples : Apport en produits azotés ; Eutrophisation', 'CARET', 'Validé', '2.2.5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1326, 64, '2.2.6', '2_2_6', 'Modification des apports en matériel organique dans le milieu', 'Augmentation ou réduction locale de la concentration en matière organique (restes de biote et microbiote morts (terre et mer), matières foecales, matière organique colloïdale floculée et restes dégradés de matières usées, déchets domestiques, déchets industriels, etc.) par rapport aux concentrations de référence du milieu (eg. mesure de la concentration en chlorophylle a)\n\nExemples : Épandage de fertilisants organiques ; Rejets domestiques et industriels ; Ruissellement agricole ; Dépôts de crues ; Laisses de mer', 'CARET', 'Validé', '2.2.6', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1327, 64, '2.2.7', '2_2_7', 'Désoxygénation du milieu', 'Réduction des niveaux d''oxygène dans l''eau ou le substrat (certaines zones peuvent être naturellement désoxygénées par la stagnation/stratification des masses d''eau). Les concentrations d''oxygène supérieures à  6 mg/l sont considérées comme favorables à  la vie marine avec des problèmes minimes, tandis que les concentrations inférieures à  2 mg/l (hypoxie, c''est-à -dire manque d''oxygène) sont considérées comme causant de graves problèmes (Best et al., 2007 ; Levin et al., 2009)).\n\nExemples : Manque d''oxygène par stagnation/stratification des masses d''eau', 'CARET', 'Validé', '2.2.7', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1328, 64, '2.3', '2_3', 'Modification des champs électromagnétiques du milieu', 'Modification des ondes électromagnétiques agissant dans le milieu\n\nExemples : Pollution lumineuse, ondes radio', 'CARET', 'Validé', '2.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1329, 64, '2.3.1', '2_3_1', 'Modification de l''intensité lumineuse dans le milieu', 'Augmentation ou réduction de l''intensité lumineuse\n\nExemples : Augmentation ou diminution de l''intensité lumineuse', 'CARET', 'Validé', '2.3.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1330, 64, '2.3.1.1', '2_3_1_1', 'Augmentation de l''intensité lumineuse dans le milieu', 'Augmentation de la quantité de lumière artificielle incidente (eg. Introduction de lumière artificielle ou modification du couvert végétal)\n\nExemples : Eclairage des cavités ; Eclairage public le long des plages', 'CARET', 'Validé', '2.3.1.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1331, 64, '2.3.1.2', '2_3_1_2', 'Diminution de l''intensité lumineuse dans le milieu', 'Diminution de la lumière naturelle incidente (eg. par des sources anthropiques (pontons flottants par exemple) ou par la prolifération d''espèce (modification du couvert végétal))\n\nExemples : Pontons flottants', 'CARET', 'Validé', '2.3.1.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1332, 64, '2.4', '2_4', 'Modification des émissions d''ondes sonores dans le milieu', 'Augmentation du niveau sonore audible au-dessus des niveaux naturels de bruit de fond (le spectre audible dépend des espèces)\n\nExemples : Pollution sonore : Bruit de moteur dans l''eau et dans l''air ; Bruit provenant des autoroutes, des avions ; Sonar des sous-marins dérangeant les baleines', 'CARET', 'Validé', '2.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1333, 64, '2.5', '2_5', 'Introduction de déchets solides dans le milieu', 'Apport ou perte d''objets solides manufacturés ou transformés (non-naturels) et leurs composés de dégradation (par exemple les particules de microplastiques)\n\nExemples : Pollution Déchets, Macro-déchets, Détritus', 'CARET', 'Validé', '2.5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1334, 64, '2.5.1', '2_5_1', 'Introduction de déchets plastiques dans le milieu', 'Introduction intentionnelle ou non de déchets plastiques dans le milieu\n\nExemples : Déchets plastiques', 'CARET', 'Validé', '2.5.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1335, 64, '2.5.2', '2_5_2', 'Introduction de déchets textiles dans le milieu', 'Introduction intentionnelle ou non de déchets textiles dans le milieu\n\nExemples : Déchets textiles', 'CARET', 'Validé', '2.5.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1336, 64, '2.5.3', '2_5_3', 'Introduction de déchets en verre dans le milieu', 'Introduction intentionnelle ou non de déchets en verre dans le milieu\n\nExemples : Déchets verre', 'CARET', 'Validé', '2.5.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1337, 64, '2.5.4', '2_5_4', 'Introduction de déchets en métaux dans le milieu', 'Introduction intentionnelle ou non de déchets métalliques dans le milieu\n\nExemples : Déchets métaux', 'CARET', 'Validé', '2.5.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1338, 64, '2.5.5', '2_5_5', 'Introduction de déchets en matériau naturel dans le milieu', 'Introduction intentionnelle ou non de déchets de matériaux naturels dans le milieu\n\nExemples : Déchet matériaux', 'CARET', 'Validé', '2.5.5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1339, 64, '2.5.6', '2_5_6', 'Introduction de déchet à caractère visqueux dans le milieu', 'Introduction intentionnelle ou non de déchets à  caractère visqueux (généralement hydrophobes), comme les huiles, les paraffines ou les hydrocarbures.\n\nExemples : Déchets visqueux', 'CARET', 'Validé', '2.5.6', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1340, 64, '2.6', '2_6', 'Introduction de substances chimiques dans le milieu', 'Introduction dans le milieu de substance chimique pouvant être contaminante\n\nExemples : Pollution chimique', 'CARET', 'Validé', '2.6', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1341, 64, '2.6.1', '2_6_1', 'Introduction de métaux, métalloïdes et ETM dans le milieu', 'Dépassement des seuils de concentration d''un ou plusieurs éléments traces métalliques, métalloïdes et/ou organo-métaux dans les compartiments pertinents (eau, biote ou sédiment), au-delà  desquels il y a une probabilité non-nulle d''observer un effet toxique pour l''habitat. (eg. les principaux éléments métalliques préoccupants pour les sédiments marins sont : Cuivre, Zinc, et d''autres plus toxiques tels que l''Argent, le Cadmium, le Plomb, le Mercure, le Chrome, le Cobalt et l''Arsenic)\n\nExemples : Contamination au mercure', 'CARET', 'Validé', '2.6.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1342, 64, '2.6.2', '2_6_2', 'Introduction d''hydrocarbures et HAP dans le milieu', 'Dépassement des seuils de concentration d''un ou plusieurs hydrocarbures et HAP dans les compartiments pertinents (eau, biote ou sédiment), au-delà  desquels il y a une probabilité non-nulle d''observer un effet toxique pour l''habitat.\n\nExemples : Rejets d''hydrocarbures de plaisance ; fuites des réservoirs de carburant', 'CARET', 'Validé', '2.6.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1343, 64, '2.6.3', '2_6_3', 'Introduction de composés synthéthiques dans le milieu', 'Introduction de composés synthétiques dans le milieu tels que les phénols, les phtalates, les composés organochlorés (incluant les PCBs, le DDT et les dioxines), les retardateurs de flamme bromés (PBDEs), les composés perfluorés, les produits phytosanitaires et les produits biocides à  usage non-agricole (insecticides, herbicides, rodenticides et fongicides), les produits pharmaceutiques (médicaux ou vétérinaires), les produits cosmétiques et d''hygiène corporelle, etc.\n\nExemples : Introduction de produits phyto-sanitaires ; Déversements illégaux de produits chimiques ; Introduction de produits cosmétiques (crèmes solaires)', 'CARET', 'Validé', '2.6.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1344, 64, '3', '3', 'Biologiques', 'Pressions exercées par des organismes (hors humain) sur le milieu (déséquilibre entre espèces)\n\nExemples : Colonisation, Prolifération, Introduction', 'CARET', 'Validé', '3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1345, 64, '3.1', '3_1', 'Introduction ou propagation d''espèces non indigènes-exotiques', 'Plantes et animaux introduits et/ou qui se propagent dans un écosystème ou un habitat dont ils ne sont pas originaires (hors de l''aire de répartition naturelle)\n\nExemples : Colonisation, envahissement par des espèces exotiques envahissantes (EEE)', 'CARET', 'Validé', '3.1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1346, 64, '3.2', '3_2', 'Introduction ou propagation d''agents pathogènes non indigènes exotiques', 'Agents pathogènes et microbes introduits et/ou qui se propagent dans un écosystème ou un habitat dont ils ne sont pas originaires (hors de l''aire de répartition naturelle)\n\nExemples : Contamination microbiologique (virus, bactérie, moisissures…). Introduction de pathogènes ou parasites', 'CARET', 'Validé', '3.2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1347, 64, '3.3', '3_3', 'Prolifération d''espèces ou d''agent pathogène indigènes', 'Augmentation incontrôlée de l''abondance de plantes, d''animaux, d''agents pathogènes ou de microbes dans un ecosystème ou un habitat dont ils sont originaires (dans l''aire de répartition naturelle)\n\nExemples : Colonisation par les ligneux, embroussaillement ; Bloom phytoplanctoniques', 'CARET', 'Validé', '3.3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1348, 64, '3.4', '3_4', 'Introduction ou translocation d''espèces, identiques aux espèces indigènes, non génétiquement modifiées', 'Introduction ou transferts d''individus d''une espèce dans une autre aire de répartition de l''espèce. Risques associés à  la dispersion d''individus transférés, en dehors de la zone visée ainsi que leur interaction avec les populations locales de la même espèce.\n\nExemples : Réintroduction d''une espèces disparue ; Repeuplement avec des espèces indigènes ; Translocation (transfert) d''espèces', 'CARET', 'Validé', '3.4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1349, 64, '3.5', '3_5', 'Introduction ou translocation d''espèces, identiques aux espèces indigènes, génétiquement modifiées (OGM)', 'Introduction d''espèces identiques aux espèces indigènes génétiquement modifiées (OGM)\n\nExemples : pas en AP', 'CARET', 'Validé', '3.5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1350, 64, '3.6', '3_6', 'Appauvrissement génétique des populations naturelles', 'Surreprésentation ou sous-représentation de certains allèles dans le profil génétique d''une population (modification des équilibres allèliques et génotypiques)\n\nExemples : Hybridation', 'CARET', 'Validé', '3.6', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1353, 64, 'AUTRE', 'AUTRE', 'Autre (pression non répertoriée)', 'Pression non présente dans le référentiel PressRef CARET V1. Permet de saisir une pression libre.', 'CICADA', 'Validé', '99', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1360, 65, 'CEN', 'CEN', 'Conservatoire d''espaces naturels', 'Conservatoire d''espaces naturels (CEN) et Fédération des CEN (FCEN)', 'CICADA', 'Validé', '1', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1361, 65, 'RNF', 'RNF', 'Réserves Naturelles de France', 'Réserves Naturelles de France (RNF) et réserves naturelles', 'CICADA', 'Validé', '2', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1362, 65, 'DREAL', 'DREAL', 'DREAL / DRIEAT', 'Direction régionale de l''environnement, de l''aménagement et du logement', 'CICADA', 'Validé', '3', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1363, 65, 'PNR', 'PNR', 'Parc naturel régional', 'Parc naturel régional', 'CICADA', 'Validé', '4', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1364, 65, 'OFB', 'OFB', 'Office français de la biodiversité', 'Office français de la biodiversité', 'CICADA', 'Validé', '5', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1365, 65, 'PNX', 'PNX', 'Parc national', 'Parc national (PNX)', 'CICADA', 'Validé', '6', NOW(), NOW(), true);
INSERT INTO ref_nomenclatures.t_nomenclatures (id_nomenclature, id_type, cd_nomenclature, mnemonique, label, definition, source, statut, hierarchy, date_ajout, date_maj, actif) VALUES (1366, 65, 'AUTRE', 'AUTRE', 'Autre', 'Autre type d''organisme gestionnaire', 'CICADA', 'Validé', '99', NOW(), NOW(), true);
